\begin{align*} a \equiv \pm \sqrt{\frac{5 \cdot 2^{2} \cdot 7 \cdot 5 \cdot 3^{2}}{2^{2} \cdot 7}} \equiv \pm \sqrt{5^{2} \cdot 3^{2}} \equiv \pm 5 \cdot 3 \equiv \pm 15 \end{align}
