\begin{align*}
\mathfrak{quantification} \equiv \mathfrak{factorization}[ \zeta \in \mathbb{R} \plus, \mathcal{L}_{XY} \plus \mathcal{L}_{XZ} \equiv \mathcal{L}_{YZ} ].
